# Case status -> the status of its one job. A closed case only counts as done
# work if an organisation held it (a duplicate closed unclaimed did no work).
ACTIVE_STATUS = {"claimed": "claimed", "in_progress": "in_progress", "pending_confirm": "pending_confirm"}


def case_claims_to_jobs(apps, schema_editor):
    CaseRecord = apps.get_model("cases", "CaseRecord")
    CaseJob = apps.get_model("cases", "CaseJob")
    CaseTask = apps.get_model("cases", "CaseTask")
    for case in CaseRecord.objects.all().iterator():
        if case.status in ACTIVE_STATUS and case.claimed_by_org_id:
            status = ACTIVE_STATUS[case.status]
        elif case.status == "closed" and case.claimed_by_org_id:
            status = "done"
        else:
            status = "open"
        job = CaseJob.objects.create(
            case=case,
            help_type=case.damage_category,
            status=status,
            claimed_by_org_id=case.claimed_by_org_id,
            completed_at=case.closed_at if status == "done" else None,
        )
        CaseTask.objects.filter(case=case).update(job=job)


